pub const IV: [u32; 8] = [
    0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A,
    0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19,
];

pub const MSG_PERMUTATION: [usize; 16] = [
    2, 6, 3, 10, 7, 0, 4, 13, 1, 11, 12, 5, 9, 14, 15, 8,
];

pub const CHUNK_START: u32         = 1 << 0;
pub const CHUNK_END: u32           = 1 << 1;
pub const PARENT: u32              = 1 << 2;
pub const ROOT: u32                = 1 << 3;
pub const KEYED_HASH: u32          = 1 << 4;
pub const DERIVE_KEY_CONTEXT: u32  = 1 << 5;
pub const DERIVE_KEY_MATERIAL: u32 = 1 << 6;

#[inline(always)]
fn rotr32(w: u32, r: u32) -> u32 {
    w.rotate_right(r)
}

#[inline(always)]
fn g(v: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize, x: u32, y: u32) {
    v[a] = v[a].wrapping_add(v[b]).wrapping_add(x);
    v[d] = rotr32(v[d] ^ v[a], 16);
    v[c] = v[c].wrapping_add(v[d]);
    v[b] = rotr32(v[b] ^ v[c], 12);
    v[a] = v[a].wrapping_add(v[b]).wrapping_add(y);
    v[d] = rotr32(v[d] ^ v[a], 8);
    v[c] = v[c].wrapping_add(v[d]);
    v[b] = rotr32(v[b] ^ v[c], 7);
}

pub fn compress(
    cv: &[u32; 8],
    block_words: &[u32; 16],
    block_len: u32,
    counter: u64,
    flags: u32,
) -> [u32; 16] {
    let mut v = [0u32; 16];
    v[0..8].copy_from_slice(cv);
    v[8..12].copy_from_slice(&IV[0..4]);
    v[12] = counter as u32;
    v[13] = (counter >> 32) as u32;
    v[14] = block_len;
    v[15] = flags;

    let mut m = *block_words;
    for _ in 0..7 {
        // column step
        g(&mut v, 0, 4,  8, 12, m[0], m[1]);
        g(&mut v, 1, 5,  9, 13, m[2], m[3]);
        g(&mut v, 2, 6, 10, 14, m[4], m[5]);
        g(&mut v, 3, 7, 11, 15, m[6], m[7]);
        // diagonal step
        g(&mut v, 0, 5, 10, 15, m[8], m[9]);
        g(&mut v, 1, 6, 11, 12, m[10], m[11]);
        g(&mut v, 2, 7,  8, 13, m[12], m[13]);
        g(&mut v, 3, 4,  9, 14, m[14], m[15]);
        // permute
        let mut next_m = [0u32; 16];
        for i in 0..16 {
            next_m[i] = m[MSG_PERMUTATION[i]];
        }
        m = next_m;
    }

    v
}

pub fn bytes_to_words(block: &[u8]) -> [u32; 16] {
    let mut padded = [0u8; 64];
    padded[..block.len()].copy_from_slice(block);
    let mut words = [0u32; 16];
    for i in 0..16 {
        words[i] = u32::from_le_bytes(padded[i * 4..(i + 1) * 4].try_into().unwrap());
    }
    words
}

#[derive(Clone, Debug)]
pub struct OutputNode {
    pub cv: [u32; 8],
    pub block_words: [u32; 16],
    pub block_len: u32,
    pub counter: u64,
    pub flags: u32,
}

impl OutputNode {
    pub fn chaining_value(&self) -> [u32; 8] {
        let v = compress(&self.cv, &self.block_words, self.block_len, self.counter, self.flags);
        let mut cv = [0u32; 8];
        for i in 0..8 {
            cv[i] = v[i] ^ v[i + 8];
        }
        cv
    }

    pub fn squeeze(&self, seek: u64, out: &mut [u8]) {
        let mut out_pos = 0;
        let mut out_block_counter = seek / 64;
        let mut byte_offset = (seek % 64) as usize;

        while out_pos < out.len() {
            let v = compress(
                &self.cv,
                &self.block_words,
                self.block_len,
                out_block_counter,
                self.flags | ROOT,
            );
            let mut words = [0u32; 16];
            for i in 0..8 {
                words[i] = v[i] ^ v[i + 8];
            }
            for i in 0..8 {
                words[i + 8] = v[i + 8] ^ self.cv[i];
            }
            let mut block_bytes = [0u8; 64];
            for i in 0..16 {
                block_bytes[i * 4..(i + 1) * 4].copy_from_slice(&words[i].to_le_bytes());
            }

            let available = &block_bytes[byte_offset..];
            let needed = out.len() - out_pos;
            let take = available.len().min(needed);

            out[out_pos..out_pos + take].copy_from_slice(&available[..take]);
            out_pos += take;
            byte_offset = 0;
            out_block_counter += 1;
        }
    }
}

pub fn parent_cv(left_cv: &[u32; 8], right_cv: &[u32; 8], key_words: &[u32; 8], flags: u32) -> [u32; 8] {
    let mut block_words = [0u32; 16];
    block_words[0..8].copy_from_slice(left_cv);
    block_words[8..16].copy_from_slice(right_cv);
    let v = compress(key_words, &block_words, 64, 0, flags | PARENT);
    let mut cv = [0u32; 8];
    for i in 0..8 {
        cv[i] = v[i] ^ v[i + 8];
    }
    cv
}

pub fn parent_output(left_cv: &[u32; 8], right_cv: &[u32; 8], key_words: &[u32; 8], flags: u32) -> OutputNode {
    let mut block_words = [0u32; 16];
    block_words[0..8].copy_from_slice(left_cv);
    block_words[8..16].copy_from_slice(right_cv);
    OutputNode {
        cv: *key_words,
        block_words,
        block_len: 64,
        counter: 0,
        flags: flags | PARENT,
    }
}

pub fn hash_chunk(data: &[u8], key_words: &[u32; 8], chunk_index: u64, flags: u32) -> OutputNode {
    let mut cv = *key_words;
    let num_blocks = if data.is_empty() { 1 } else { (data.len() + 63) / 64 };

    for i in 0..num_blocks {
        let start = i * 64;
        let end = (start + 64).min(data.len());
        let block = if start < data.len() { &data[start..end] } else { &[] };
        let b_len = block.len() as u32;
        let b_words = bytes_to_words(block);
        let mut b_flags = flags;
        if i == 0 {
            b_flags |= CHUNK_START;
        }
        if i == num_blocks - 1 {
            b_flags |= CHUNK_END;
        }

        if i == num_blocks - 1 {
            return OutputNode {
                cv,
                block_words: b_words,
                block_len: b_len,
                counter: chunk_index,
                flags: b_flags,
            };
        } else {
            let v = compress(&cv, &b_words, b_len, chunk_index, b_flags);
            for j in 0..8 {
                cv[j] = v[j] ^ v[j + 8];
            }
        }
    }

    unreachable!()
}

pub struct Hasher {
    key_words: [u32; 8],
    flags: u32,
    cv_stack: Vec<[u32; 8]>,
    current_chunk_buf: Vec<u8>,
    chunk_counter: u64,
}

impl Hasher {
    pub fn new() -> Self {
        Self {
            key_words: IV,
            flags: 0,
            cv_stack: Vec::new(),
            current_chunk_buf: Vec::with_capacity(1024),
            chunk_counter: 0,
        }
    }

    pub fn new_keyed(key_bytes: &[u8; 32]) -> Self {
        let mut key_words = [0u32; 8];
        for i in 0..8 {
            key_words[i] = u32::from_le_bytes(key_bytes[i * 4..(i + 1) * 4].try_into().unwrap());
        }
        Self {
            key_words,
            flags: KEYED_HASH,
            cv_stack: Vec::new(),
            current_chunk_buf: Vec::with_capacity(1024),
            chunk_counter: 0,
        }
    }

    pub fn new_derive_key(context: &str) -> Self {
        let mut ctx_hasher = Self {
            key_words: IV,
            flags: DERIVE_KEY_CONTEXT,
            cv_stack: Vec::new(),
            current_chunk_buf: Vec::with_capacity(1024),
            chunk_counter: 0,
        };
        ctx_hasher.update(context.as_bytes());
        let mut ctx_key = [0u8; 32];
        ctx_hasher.finalize(0, &mut ctx_key);

        let mut key_words = [0u32; 8];
        for i in 0..8 {
            key_words[i] = u32::from_le_bytes(ctx_key[i * 4..(i + 1) * 4].try_into().unwrap());
        }

        Self {
            key_words,
            flags: DERIVE_KEY_MATERIAL,
            cv_stack: Vec::new(),
            current_chunk_buf: Vec::with_capacity(1024),
            chunk_counter: 0,
        }
    }

    pub fn update(&mut self, mut input: &[u8]) {
        while !input.is_empty() {
            if self.current_chunk_buf.len() == 1024 {
                let out_node = hash_chunk(
                    &self.current_chunk_buf,
                    &self.key_words,
                    self.chunk_counter,
                    self.flags,
                );
                let mut cv = out_node.chaining_value();
                let mut total_chunks = self.chunk_counter + 1;

                while (total_chunks & 1) == 0 {
                    let left_cv = self.cv_stack.pop().unwrap();
                    cv = parent_cv(&left_cv, &cv, &self.key_words, self.flags);
                    total_chunks >>= 1;
                }

                self.cv_stack.push(cv);
                self.chunk_counter += 1;
                self.current_chunk_buf.clear();
            }

            let needed = 1024 - self.current_chunk_buf.len();
            let take = needed.min(input.len());
            self.current_chunk_buf.extend_from_slice(&input[..take]);
            input = &input[take..];
        }
    }

    pub fn finalize(&self, seek: u64, out: &mut [u8]) {
        let out_node = hash_chunk(
            &self.current_chunk_buf,
            &self.key_words,
            self.chunk_counter,
            self.flags,
        );

        if self.chunk_counter == 0 {
            out_node.squeeze(seek, out);
        } else {
            let mut right_cv = out_node.chaining_value();
            let mut stack = self.cv_stack.clone();

            while stack.len() > 1 {
                let left_cv = stack.pop().unwrap();
                right_cv = parent_cv(&left_cv, &right_cv, &self.key_words, self.flags);
            }

            let left_cv = stack.pop().unwrap();
            let root_node = parent_output(&left_cv, &right_cv, &self.key_words, self.flags);
            root_node.squeeze(seek, out);
        }
    }
}
