    counter: u64,
    flags: u32,
) -> [u32; 16] {
    let mut v = [0u32; 16];
    v[0..8].copy_from_slice(cv);
    v[8..12].copy_from_slice(&IV[0..4]);
    v[12] = counter as u32;
    v[13] = (counter >> 32) as u32;
    v[14] = block_len;
    v[15] = flags;

    let mut m = *block_words;
    for _ in 0..7 {
        // column step
        g(&mut v, 0, 4,  8, 12, m[0], m[1]);
        g(&mut v, 1, 5,  9, 13, m[2], m[3]);
        g(&mut v, 2, 6, 10, 14, m[4], m[5]);
        g(&mut v, 3, 7, 11, 15, m[6], m[7]);
        // diagonal step
        g(&mut v, 0, 5, 10, 15, m[8], m[9]);
        g(&mut v, 1, 6, 11, 12, m[10], m[11]);
        g(&mut v, 2, 7,  8, 13, m[12], m[13]);
        g(&mut v, 3, 4,  9, 14, m[14], m[15]);
        // permute
        let mut next_m = [0u32; 16];
        for i in 0..16 {
            next_m[i] = m[MSG_PERMUTATION[i]];
        }
        m = next_m;
    }

    v
}

pub fn bytes_to_words(block: &[u8]) -> [u32; 16] {
    let mut padded = [0u8; 64];
    padded[..block.len()].copy_from_slice(block);
    let mut words = [0u32; 16];
    for i in 0..16 {
        words[i] = u32::from_le_bytes(padded[i * 4..(i + 1) * 4].try_into().unwrap());
    }
    words
}

#[derive(Clone, Debug)]
pub struct OutputNode {
    pub cv: [u32; 8],
    pub block_words: [u32; 16],
    pub block_len: u32,
    pub counter: u64,
    pub flags: u32,
}

impl OutputNode {
    pub fn chaining_value(&self) -> [u32; 8] {
        let v = compress(&self.cv, &self.block_words, self.block_len, self.counter, self.flags);
        let mut cv = [0u32; 8];
        for i in 0..8 {
            cv[i] = v[i] ^ v[i + 8];
        }
        cv
    }

    pub fn squeeze(&self, seek: u64, out: &mut [u8]) {
        let mut out_pos = 0;
        let mut out_block_counter = seek / 64;
        let mut byte_offset = (seek % 64) as usize;

        while out_pos < out.len() {
            let v = compress(
                &self.cv,
                &self.block_words,
                self.block_len,
                out_block_counter,
                self.flags | ROOT,
            );
            let mut words = [0u32; 16];
            for i in 0..8 {
                words[i] = v[i] ^ v[i + 8];
            }
            for i in 0..8 {
                words[i + 8] = v[i + 8] ^ self.cv[i];
            }
            let mut block_bytes = [0u8; 64];
            for i in 0..16 {
                block_bytes[i * 4..(i + 1) * 4].copy_from_slice(&words[i].to_le_bytes());
            }

            let available = &block_bytes[byte_offset..];
            let needed = out.len() - out_pos;
            let take = available.len().min(needed);

            out[out_pos..out_pos + take].copy_from_slice(&available[..take]);
            out_pos += take;
            byte_offset = 0;
            out_block_counter += 1;
        }
    }
}

pub fn parent_cv(left_cv: &[u32; 8], right_cv: &[u32; 8], key_words: &[u32; 8], flags: u32) -> [u32; 8] {
    let mut block_words = [0u32; 16];
    block_words[0..8].copy_from_slice(left_cv);
    block_words[8..16].copy_from_slice(right_cv);
    let v = compress(key_words, &block_words, 64, 0, flags | PARENT);
    let mut cv = [0u32; 8];
    for i in 0..8 {
        cv[i] = v[i] ^ v[i + 8];
    }
    cv
}

pub fn parent_output(left_cv: &[u32; 8], right_cv: &[u32; 8], key_words: &[u32; 8], flags: u32) -> OutputNode {
    let mut block_words = [0u32; 16];
    block_words[0..8].copy_from_slice(left_cv);
    block_words[8..16].copy_from_slice(right_cv);
    OutputNode {
        cv: *key_words,
        block_words,
        block_len: 64,
        counter: 0,
        flags: flags | PARENT,
    }
}

pub fn hash_chunk(data: &[u8], key_words: &[u32; 8], chunk_index: u64, flags: u32) -> OutputNode {
    let mut cv = *key_words;
    let num_blocks = if data.is_empty() { 1 } else { (data.len() + 63) / 64 };

    for i in 0..num_blocks {
        let start = i * 64;
        let end = (start + 64).min(data.len());
        let block = if start < data.len() { &data[start..end] } else { &[] };
        let b_len = block.len() as u32;
        let b_words = bytes_to_words(block);
        let mut b_flags = flags;
        if i == 0 {
            b_flags |= CHUNK_START;
        }
        if i == num_blocks - 1 {
            b_flags |= CHUNK_END;
        }

        if i == num_blocks - 1 {
            return OutputNode {
                cv,
                block_words: b_words,
                block_len: b_len,
                counter: chunk_index,
                flags: b_flags,
            };
        } else {
            let v = compress(&cv, &b_words, b_len, chunk_index, b_flags);
            for j in 0..8 {
                cv[j] = v[j] ^ v[j + 8];
            }
        }
    }

    unreachable!()
}

pub struct Hasher {
    key_words: [u32; 8],
    flags: u32,
    cv_stack: Vec<[u32; 8]>,
    current_chunk_buf: Vec<u8>,
    chunk_counter: u64,
}

impl Hasher {
    pub fn new() -> Self {
        Self {
            key_words: IV,
            flags: 0,
            cv_stack: Vec::new(),
            current_chunk_buf: Vec::with_capacity(1024),
            chunk_counter: 0,
        }
    }

    pub fn new_keyed(key_bytes: &[u8; 32]) -> Self {
        let mut key_words = [0u32; 8];
        for i in 0..8 {
            key_words[i] = u32::from_le_bytes(key_bytes[i * 4..(i + 1) * 4].try_into().unwrap());
        }
        Self {
            key_words,
            flags: KEYED_HASH,
            cv_stack: Vec::new(),
            current_chunk_buf: Vec::with_capacity(1024),
            chunk_counter: 0,
        }
    }

    pub fn new_derive_key(context: &str) -> Self {
        let mut ctx_hasher = Self {
            key_words: IV,
            flags: DERIVE_KEY_CONTEXT,
            cv_stack: Vec::new(),
            current_chunk_buf: Vec::with_capacity(1024),
            chunk_counter: 0,
        };
        ctx_hasher.update(context.as_bytes());
        let mut ctx_key = [0u8; 32];
        ctx_hasher.finalize(0, &mut ctx_key);

        let mut key_words = [0u32; 8];
        for i in 0..8 {
            key_words[i] = u32::from_le_bytes(ctx_key[i * 4..(i + 1) * 4].try_into().unwrap());
        }

        Self {
            key_words,
            flags: DERIVE_KEY_MATERIAL,
            cv_stack: Vec::new(),
            current_chunk_buf: Vec::with_capacity(1024),
            chunk_counter: 0,
        }
    }

    pub fn update(&mut self, mut input: &[u8]) {
        while !input.is_empty() {
            if self.current_chunk_buf.len() == 1024 {
                let out_node = hash_chunk(
                    &self.current_chunk_buf,
                    &self.key_words,
                    self.chunk_counter,
                    self.flags,
                );
                let mut cv = out_node.chaining_value();
                let mut total_chunks = self.chunk_counter + 1;

                while (total_chunks & 1) == 0 {
                    let left_cv = self.cv_stack.pop().unwrap();
                    cv = parent_cv(&left_cv, &cv, &self.key_words, self.flags);
                    total_chunks >>= 1;
                }

                self.cv_stack.push(cv);
                self.chunk_counter += 1;
                self.current_chunk_buf.clear();
            }

            let needed = 1024 - self.current_chunk_buf.len();
            let take = needed.min(input.len());
            self.current_chunk_buf.extend_from_slice(&input[..take]);
            input = &input[take..];
        }
    }

    pub fn finalize(&self, seek: u64, out: &mut [u8]) {
        let out_node = hash_chunk(
            &self.current_chunk_buf,
            &self.key_words,
            self.chunk_counter,
            self.flags,
        );

        if self.chunk_counter == 0 {
            out_node.squeeze(seek, out);
        } else {
            let mut right_cv = out_node.chaining_value();
            let mut stack = self.cv_stack.clone();

            while stack.len() > 1 {
                let left_cv = stack.pop().unwrap();
                right_cv = parent_cv(&left_cv, &right_cv, &self.key_words, self.flags);
            }

            let left_cv = stack.pop().unwrap();
            let root_node = parent_output(&left_cv, &right_cv, &self.key_words, self.flags);
            root_node.squeeze(seek, out);
        }
    }
}
EOF
"}

{"command":"cat <<'EOF' > src/cli.rs
use std::env;
use std::path::Path;
use std::process;

pub struct Cli {
    pub files: Vec<String>,
    pub keyed: bool,
    pub derive_key: Option<String>,
    pub length: u64,
    pub explicit_length: bool,
    pub seek: u64,
    pub num_threads: usize,
    pub no_mmap: bool,
    pub no_names: bool,
    pub raw: bool,
    pub tag: bool,
    pub check: bool,
    pub quiet: bool,
}

pub fn parse_args() -> Cli {
    let args: Vec<String> = env::args().collect();
    let prog_name = args.first()
        .and_then(|s| Path::new(s).file_name())
        .and_then(|s| s.to_str())
        .unwrap_or("executable");

    let mut files = Vec::new();
    let mut keyed = false;
    let mut derive_key = None;
    let mut length = 32u64;
    let mut explicit_length = false;
    let mut seek = 0u64;
    let mut num_threads = 0usize;
    let mut no_mmap = false;
    let mut no_names = false;
    let mut raw = false;
    let mut tag = false;
    let mut check = false;
    let mut quiet = false;

    // Track explicit options in order of appearance
    let mut option_order: Vec<(&'static str, &'static str)> = Vec::new();

    let mut i = 1;
    let mut parsing_options = true;

    while i < args.len() {
        let arg = &args[i];

        if parsing_options && arg == "--" {
            parsing_options = false;
            i += 1;
            continue;
        }

        if parsing_options && arg.starts_with('-') && arg != "-" {
            if arg == "-h" {
                print_short_help(prog_name);
                process::exit(0);
            } else if arg == "--help" {
                print_long_help(prog_name);
                process::exit(0);
            } else if arg == "-V" || arg == "--version" {
                println!("b3sum 1.8.4");
                process::exit(0);
            } else if arg == "--keyed" {
                keyed = true;
                option_order.push(("--keyed", "--keyed"));
                i += 1;
            } else if arg == "--derive-key" || arg.starts_with("--derive-key=") {
                let val = if let Some(eq_idx) = arg.find('=') {
                    arg[eq_idx + 1..].to_string()
                } else if i + 1 < args.len() {
                    i += 1;
                    args[i].clone()
                } else {
                    eprintln!("error: a value is required for '--derive-key <CONTEXT>' but none was supplied\n\nFor more information, try '--help'.");
                    process::exit(2);
                };
                derive_key = Some(val);
                option_order.push(("--derive-key", "--derive-key <CONTEXT>"));
                i += 1;
            } else if arg == "-l" || arg.starts_with("-l") || arg == "--length" || arg.starts_with("--length=") {
                let val_str = if arg == "-l" || arg == "--length" {
                    if i + 1 < args.len() {
                        i += 1;
                        &args[i]
                    } else {
                        eprintln!("error: a value is required for '--length <LEN>' but none was supplied\n\nFor more information, try '--help'.");
                        process::exit(2);
                    }
                } else if arg.starts_with("--length=") {
                    &arg["--length=".len()..]
                } else {
                    // -l<VAL>
                    &arg[2..]
                };

                match val_str.parse::<u64>() {
                    Ok(val) => {
                        length = val;
                        explicit_length = true;
                        option_order.push(("--length", "--length <LEN>"));
                    }
                    Err(_) => {
                        eprintln!("error: invalid value '{}' for '--length <LEN>': invalid digit found in string\n\nFor more information, try '--help'.", val_str);
                        process::exit(2);
                    }
                }
                i += 1;
            } else if arg == "--seek" || arg.starts_with("--seek=") {
                let val_str = if arg == "--seek" {
                    if i + 1 < args.len() {
                        i += 1;
                        &args[i]
                    } else {
                        eprintln!("error: a value is required for '--seek <SEEK>' but none was supplied\n\nFor more information, try '--help'.");
                        process::exit(2);
                    }
                } else {
                    &arg["--seek=".len()..]
                };

                match val_str.parse::<u64>() {
                    Ok(val) => {
                        seek = val;
                    }
                    Err(_) => {
                        eprintln!("error: invalid value '{}' for '--seek <SEEK>': invalid digit found in string\n\nFor more information, try '--help'.", val_str);
                        process::exit(2);
                    }
                }
                i += 1;
            } else if arg == "--num-threads" || arg.starts_with("--num-threads=") {
                let val_str = if arg == "--num-threads" {
                    if i + 1 < args.len() {
                        i += 1;
                        &args[i]
                    } else {
                        eprintln!("error: a value is required for '--num-threads <NUM>' but none was supplied\n\nFor more information, try '--help'.");
                        process::exit(2);
                    }
                } else {
                    &arg["--num-threads=".len()..]
                };

                match val_str.parse::<usize>() {
                    Ok(val) => {
                        num_threads = val;
                    }
                    Err(_) => {
                        eprintln!("error: invalid value '{}' for '--num-threads <NUM>': invalid digit found in string\n\nFor more information, try '--help'.", val_str);
                        process::exit(2);
                    }
                }
                i += 1;
            } else if arg == "--no-mmap" {
                no_mmap = true;
                i += 1;
            } else if arg == "--no-names" {
                no_names = true;
                option_order.push(("--no-names", "--no-names"));
                i += 1;
            } else if arg == "--raw" {
                raw = true;
                option_order.push(("--raw", "--raw"));
                i += 1;
            } else if arg == "--tag" {
                tag = true;
                option_order.push(("--tag", "--tag"));
                i += 1;
            } else if arg == "-c" || arg == "--check" {
                check = true;
                option_order.push(("--check", "--check"));
                i += 1;
            } else if arg == "--quiet" {
                quiet = true;
                i += 1;
            } else if arg.starts_with('-') && !arg.starts_with("--") {
                // Short options cluster e.g. -cq
                let mut chars = arg[1..].chars().peekable();
                let mut consumed_val = false;
                while let Some(ch) = chars.next() {
                    match ch {
                        'h' => {
                            print_short_help(prog_name);
                            process::exit(0);
                        }
                        'V' => {
                            println!("b3sum 1.8.4");
                            process::exit(0);
                        }
                        'c' => {
                            check = true;
                            option_order.push(("--check", "--check"));
                        }
                        'l' => {
                            let rest: String = chars.collect();
                            let val_str = if !rest.is_empty() {
                                rest
                            } else if i + 1 < args.len() {
                                i += 1;
                                args[i].clone()
                            } else {
                                eprintln!("error: a value is required for '--length <LEN>' but none was supplied\n\nFor more information, try '--help'.");
                                process::exit(2);
                            };
                            match val_str.parse::<u64>() {
                                Ok(val) => {
                                    length = val;
                                    explicit_length = true;
                                    option_order.push(("--length", "--length <LEN>"));
                                }
                                Err(_) => {
                                    eprintln!("error: invalid value '{}' for '--length <LEN>': invalid digit found in string\n\nFor more information, try '--help'.", val_str);
                                    process::exit(2);
                                }
                            }
                            consumed_val = true;
                            break;
                        }
                        _ => {
                            eprintln!("error: unexpected argument '-{}' found\n\nUsage: {} [OPTIONS] [FILE]...\n\nFor more information, try '--help'.", ch, prog_name);
                            process::exit(2);
                        }
                    }
                }
                if !consumed_val {
                    i += 1;
                } else {
                    i += 1;
                }
            } else {
                eprintln!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {} [OPTIONS] [FILE]...\n\nFor more information, try '--help'.", arg, arg, arg, prog_name);
                process::exit(2);
            }
        } else {
            files.push(arg.clone());
            i += 1;
        }
    }

    // Validations & Conflicts
    if quiet && !check {
        eprintln!("error: the following required arguments were not provided:\n  --check\n\nUsage: {} --check --quiet <FILE>...\n\nFor more information, try '--help'.", prog_name);
        process::exit(2);
    }

    if keyed && derive_key.is_some() {
        let first_is_keyed = option_order.iter().position(|(k, _)| *k == "--keyed").unwrap()
            < option_order.iter().position(|(k, _)| *k == "--derive-key").unwrap();
        if first_is_keyed {
            eprintln!("error: the argument '--derive-key <CONTEXT>' cannot be used with '--keyed'\n\nUsage: {} --keyed <FILE>...\n\nFor more information, try '--help'.", prog_name);
        } else {
            eprintln!("error: the argument '--keyed' cannot be used with '--derive-key <CONTEXT>'\n\nUsage: {} --derive-key <CONTEXT> <FILE>...\n\nFor more information, try '--help'.", prog_name);
        }
        process::exit(2);
    }

    if check {
        // Conflicts with --check
        for (key, display) in &option_order {
            if *key != "--check" {
                if *key == "--length" && !explicit_length {
                    continue;
                }
                let check_idx = option_order.iter().position(|(k, _)| *k == "--check").unwrap();
                let other_idx = option_order.iter().position(|(k, _)| k == key).unwrap();
                if check_idx < other_idx {
                    eprintln!("error: the argument '{}' cannot be used with '--check'\n\nUsage: {} --check <FILE>...\n\nFor more information, try '--help'.", display, prog_name);
                } else {
                    eprintln!("error: the argument '--check' cannot be used with '{}'\n\nUsage: {} {} <FILE>...\n\nFor more information, try '--help'.", display, prog_name, display);
                }
                process::exit(2);
            }
        }
    }

    if keyed && files.is_empty() {
        eprintln!("error: the following required arguments were not provided:\n  <FILE>...\n\nUsage: {} --keyed <FILE>...\n\nFor more information, try '--help'.", prog_name);
        process::exit(2);
    }

    Cli {
        files,
        keyed,
        derive_key,
        length,
        explicit_length,
        seek,
        num_threads,
        no_mmap,
        no_names,
        raw,
        tag,
        check,
        quiet,
    }
}

fn print_short_help(prog_name: &str) {
    println!("Usage: {} [OPTIONS] [FILE]...\n\nArguments:\n  [FILE]...  Files to hash, or checkfiles to check\n\nOptions:\n      --keyed                 Use the keyed mode, reading the 32-byte key from stdin\n      --derive-key <CONTEXT>  Use the key derivation mode, with the given context string\n  -l, --length <LEN>          The number of output bytes, before hex encoding [default: 32]\n      --seek <SEEK>           The starting output byte offset, before hex encoding [default: 0]\n      --num-threads <NUM>     The maximum number of threads to use\n      --no-mmap               Disable memory mapping\n      --no-names              Omit filenames in the output\n      --raw                   Write raw output bytes to stdout, rather than hex\n      --tag                   Output BSD-style checksums: BLAKE3 ([FILE]) = [HASH]\n  -c, --check                 Read BLAKE3 sums from the [FILE]s and check them\n      --quiet                 Skip printing OK for each checked file\n  -h, --help                  Print help (see more with '--help')\n  -V, --version               Print version", prog_name);
}

fn print_long_help(prog_name: &str) {
    println!("Usage: {} [OPTIONS] [FILE]...\n\nArguments:\n  [FILE]...\n          Files to hash, or checkfiles to check\n          \n          When no file is given, or when - is given, read standard input.\n\nOptions:\n      --keyed\n          Use the keyed mode, reading the 32-byte key from stdin\n\n      --derive-key <CONTEXT>\n          Use the key derivation mode, with the given context string\n          \n          Cannot be used with --keyed.\n\n  -l, --length <LEN>\n          The number of output bytes, before hex encoding\n          \n          [default: 32]\n\n      --seek <SEEK>\n          The starting output byte offset, before hex encoding\n          \n          [default: 0]\n\n      --num-threads <NUM>\n          The maximum number of threads to use\n          \n          By default, this is the number of logical cores. If this flag is omitted, or if its value\n          is 0, RAYON_NUM_THREADS is also respected.\n\n      --no-mmap\n          Disable memory mapping\n          \n          Currently this also disables multithreading.\n\n      --no-names\n          Omit filenames in the output\n\n      --raw\n          Write raw output bytes to stdout, rather than hex\n          \n          --no-names is implied. In this case, only a single input is allowed.\n\n      --tag\n          Output BSD-style checksums: BLAKE3 ([FILE]) = [HASH]\n\n  -c, --check\n          Read BLAKE3 sums from the [FILE]s and check them\n\n      --quiet\n          Skip printing OK for each checked file\n          \n          Must be used with --check.\n\n  -h, --help\n          Print help (see a summary with '-h')\n\n  -V, --version\n          Print version", prog_name);
}
EOF
"}

