use std::io::{self, BufRead, BufReader, Read, Write};
use std::process;

fn hex_encode(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for &b in bytes {
        s.push_str(&format!("{:02x}", b));
    }
    s
}

fn hex_decode_32(s: &str) -> Option<[u8; 32]> {
    if s.len() != 64 {
        return None;
    }
    let mut bytes = [0u8; 32];
    for i in 0..32 {
        let byte_str = &s[i * 2..i * 2 + 2];
        match u8::from_str_radix(byte_str, 16) {
            Ok(b) => bytes[i] = b,
            Err(_) => return None,
        }
    }
    Some(bytes)
}

fn main() {
    let cli = parse_args();

    if cli.check {
        run_check_mode(&cli);
    } else {
        run_hash_mode(&cli);
    }
}

fn run_hash_mode(cli: &cli::Cli) {
    let mut key = [0u8; 32];

    if cli.keyed {
        let mut key_buf = Vec::new();
        io::stdin().lock().read_to_end(&mut key_buf).unwrap();
        if key_buf.len() < 32 {
            eprintln!("Error: expected 32 key bytes from stdin, found {}", key_buf.len());
            process::exit(1);
        }
        if key_buf.len() > 32 {
            eprintln!("Error: read more than 32 key bytes from stdin");
            process::exit(1);
        }
        key.copy_from_slice(&key_buf[..32]);
    }

    if cli.raw && cli.files.len() > 1 {
        eprintln!("Error: Only one filename can be provided when using --raw");
        process::exit(1);
    }

    let files = if cli.files.is_empty() {
        vec!["-".to_string()]
    } else {
        cli.files.clone()
    };

    let mut has_error = false;

    for file in &files {
        if cli.keyed && file == "-" {
            eprintln!("b3sum: -: Cannot open `-` in keyed mode");
            has_error = true;
            continue;
        }

        let mut hasher = if cli.keyed {
            Hasher::new_keyed(&key)
        } else if let Some(ref ctx) = cli.derive_key {
            Hasher::new_derive_key(ctx)
        } else {
            Hasher::new()
        };

        let res = if file == "-" {
            read_stream(&mut io::stdin().lock(), &mut hasher)
        } else {
            match File::open(file) {
                Ok(mut f) => read_stream(&mut f, &mut hasher),
                Err(e) => Err(e),
            }
        };

        if let Err(e) = res {
            eprintln!("b3sum: {}: {}", file, e);
            has_error = true;
            continue;
        }

        let mut out_buf = vec![0u8; cli.length as usize];
        hasher.finalize(cli.seek, &mut out_buf);

        if cli.raw {
            let mut stdout = io::stdout().lock();
            stdout.write_all(&out_buf).unwrap();
            stdout.flush().unwrap();
        } else {
            let hex = hex_encode(&out_buf);
            if cli.no_names {
                println!("{}", hex);
            } else if cli.tag {
                println!("BLAKE3 ({}) = {}", file, hex);
            } else {
                println!("{}  {}", hex, file);
            }
        }
    }

    if has_error {
        process::exit(1);
    }
}

fn read_stream<R: Read>(reader: &mut R, hasher: &mut Hasher) -> io::Result<()> {
    let mut buf = [0u8; 65536];
    loop {
        let n = reader.read(&mut buf)?;
        if n == 0 {
            break;
        }
        hasher.update(&buf[..n]);
    }
    Ok(())
}

fn run_check_mode(cli: &cli::Cli) {
    let files = if cli.files.is_empty() {
        vec!["-".to_string()]
    } else {
        cli.files.clone()
    };

    let mut total_failures = 0usize;

    for file in &files {
        let mut reader: Box<dyn BufRead> = if file == "-" {
            Box::new(BufReader::new(io::stdin().lock()))
        } else {
            match File::open(file) {
                Ok(f) => Box::new(BufReader::new(f)),
                Err(e) => {
                    eprintln!("b3sum: {}: {}", file, e);
                    total_failures += 1;
                    continue;
                }
            }
        };

        let mut line_buf = String::new();
        loop {
            line_buf.clear();
            match reader.read_line(&mut line_buf) {
                Ok(0) => break, // EOF
                Ok(_) => {}
                Err(e) => {
                    eprintln!("b3sum: {}: {}", file, e);
                    total_failures += 1;
                    break;
                }
            }

            let line = line_buf.trim_end_matches(['\r', '\n']);

            if line.trim().is_empty() {
                eprintln!("b3sum: Empty line");
                total_failures += 1;
                continue;
            }

            // Parse format
            let (hash_str, path_str) = if line.starts_with("BLAKE3 (") {
                if let Some(close_paren_idx) = line.find(") = ") {
                    let path = &line["BLAKE3 (".len()..close_paren_idx];
                    let hash = &line[close_paren_idx + ") = ".len()..];
                    (hash, path)
                } else {
                    eprintln!("b3sum: Invalid check line format");
                    total_failures += 1;
                    continue;
                }
            } else if let Some(two_space_idx) = line.find("  ") {
                let hash = &line[..two_space_idx];
                let path = &line[two_space_idx + 2..];
                (hash, path)
            } else {
                eprintln!("b3sum: Invalid check line format");
                total_failures += 1;
                continue;
            };

            if hash_str.len() != 64 {
                eprintln!("b3sum: Invalid hash length");
                total_failures += 1;
                continue;
            }

            if hash_str.chars().any(|c| !c.is_ascii_hexdigit() || c.is_ascii_uppercase()) {
                eprintln!("b3sum: Invalid hex");
                total_failures += 1;
                continue;
            }

            let expected_bytes = match hex_decode_32(hash_str) {
                Some(b) => b,
                None => {
                    eprintln!("b3sum: Invalid hex");
                    total_failures += 1;
                    continue;
                }
            };

            // Check target file
            let mut hasher = Hasher::new();
            let res = if path_str == "-" {
                read_stream(&mut io::stdin().lock(), &mut hasher)
            } else {
                match File::open(path_str) {
                    Ok(mut f) => read_stream(&mut f, &mut hasher),
                    Err(e) => Err(e),
                }
            };

            let mut actual_bytes = [0u8; 32];
            match res {
                Ok(_) => {
                    hasher.finalize(cli.seek, &mut actual_bytes);
                    if actual_bytes == expected_bytes {
                        if !cli.quiet {
                            println!("{}: OK", path_str);
                        }
                    } else {
                        println!("{}: FAILED", path_str);
                        total_failures += 1;
                    }
                }
                Err(e) => {
                    println!("{}: FAILED ({})", path_str, e);
                    total_failures += 1;
                }
            }
        }
    }

    if total_failures > 0 {
        if total_failures == 1 {
            eprintln!("b3sum: WARNING: 1 computed checksum did NOT match");
        } else {
            eprintln!("b3sum: WARNING: {} computed checksums did NOT match", total_failures);
        }
        process::exit(1);
    } else {
        process::exit(0);
    }
}
EOF
