def run(cmd, input_data=None):
    p = subprocess.run(cmd, input=input_data, capture_output=True)
    return p.returncode, p.stdout, p.stderr

def test_eq(name, cmd1, cmd2, input_data=None):
    rc1, out1, err1 = run(cmd1, input_data)
    rc2, out2, err2 = run(cmd2, input_data)

    ok = True
    if rc1 != rc2:
        print(f"[{name}] RC mismatch: {rc1} vs {rc2}")
        ok = False
    if out1 != out2:
        print(f"[{name}] STDOUT mismatch:\n  Got:      {out1}\n  Expected: {out2}")
        ok = False
    if err1 != err2:
        print(f"[{name}] STDERR mismatch:\n  Got:      {err1}\n  Expected: {err2}")
        ok = False
    if ok:
        print(f"[{name}] PASSED")
    return ok

