    rc2, out2, err2 = run(cmd2, input_data)

    ok = True
    if rc1 != rc2:
        print(f"[{name}] RC mismatch: {rc1} vs {rc2}")
        ok = False
    if out1 != out2:
        print(f"[{name}] STDOUT mismatch:\n  Got:      {out1}\n  Expected: {out2}")
        ok = False
    if err1 != err2:
        print(f"[{name}] STDERR mismatch:\n  Got:      {err1}\n  Expected: {err2}")
        ok = False
    if ok:
        print(f"[{name}] PASSED")
    return ok

